       UNION ALL SELECT 'SCP0104' PROGRAM_ID, 'SOP_ELTR' SHEET_NAME, 'SOP_DT' COLUMN_NAME, 'SOP' COLUMN_LABEL_NAME, 170 SORT_ORDER_NO, 'ASC' DATA_SORT_METHOD_CODE, 'SOP' SMALL_CLASS_LABEL_NAME, 'SOP' LARGE_CLASS_LABEL_NAME, '-' FIXED_FLAG, 100 COLUMN_WIDTH, 'FPDate' CELL_CONTROL_OBJECT_TYPE_CODE, NULL CELL_COMBO_DATA_TYPE, NULL DATA_SCALE_NUMBER, NULL DATA_MAX_LENGTH, 'C' HORIZONTAL_ALIGN_CODE, '-' UPPERCASE_APPLY_FLAG, 'Y' VISIBLE_FLAG, NULL DIVISION_ID, 'Y' DEFAULT_FLAG, 'Y' USER_SELECTABLE_FLAG, 'Y' VALID_YN, NULL ATTRIBUTE1, NULL ATTRIBUTE2, NULL ATTRIBUTE3, NULL ATTRIBUTE4, NULL ATTRIBUTE5, NULL ATTRIBUTE6, NULL ATTRIBUTE7, NULL ATTRIBUTE8, NULL ATTRIBUTE9, NULL ATTRIBUTE10, 'O' INPUT_TP_CD FROM DUAL) S
