      WHERE DECODE(T.COLUMN_LABEL_NAME, S.COLUMN_LABEL_NAME, 0, 1) = 1 OR DECODE(T.SORT_ORDER_NO, S.SORT_ORDER_NO, 0, 1) = 1 OR DECODE(T.DATA_SORT_METHOD_CODE, S.DATA_SORT_METHOD_CODE, 0, 1) = 1 OR DECODE(T.SMALL_CLASS_LABEL_NAME, S.SMALL_CLASS_LABEL_NAME, 0, 1) = 1 OR DECODE(T.LARGE_CLASS_LABEL_NAME, S.LARGE_CLASS_LABEL_NAME, 0, 1) = 1 OR DECODE(T.FIXED_FLAG, S.FIXED_FLAG, 0, 1) = 1 OR DECODE(T.COLUMN_WIDTH, S.COLUMN_WIDTH, 0, 1) = 1 OR DECODE(T.CELL_CONTROL_OBJECT_TYPE_CODE, S.CELL_CONTROL_OBJECT_TYPE_CODE, 0, 1) = 1 OR DECODE(T.CELL_COMBO_DATA_TYPE, S.CELL_COMBO_DATA_TYPE, 0, 1) = 1 OR DECODE(T.DATA_SCALE_NUMBER, S.DATA_SCALE_NUMBER, 0, 1) = 1 OR DECODE(T.DATA_MAX_LENGTH, S.DATA_MAX_LENGTH, 0, 1) = 1 OR DECODE(T.HORIZONTAL_ALIGN_CODE, S.HORIZONTAL_ALIGN_CODE, 0, 1) = 1 OR DECODE(T.UPPERCASE_APPLY_FLAG, S.UPPERCASE_APPLY_FLAG, 0, 1) = 1 OR DECODE(T.VISIBLE_FLAG, S.VISIBLE_FLAG, 0, 1) = 1 OR DECODE(T.DIVISION_ID, S.DIVISION_ID, 0, 1) = 1 OR DECODE(T.DEFAULT_FLAG, S.DEFAULT_FLAG, 0, 1) = 1 OR DECODE(T.USER_SELECTABLE_FLAG, S.USER_SELECTABLE_FLAG, 0, 1) = 1 OR DECODE(T.VALID_YN, S.VALID_YN, 0, 1) = 1 OR DECODE(T.ATTRIBUTE1, S.ATTRIBUTE1, 0, 1) = 1 OR DECODE(T.ATTRIBUTE2, S.ATTRIBUTE2, 0, 1) = 1 OR DECODE(T.ATTRIBUTE3, S.ATTRIBUTE3, 0, 1) = 1 OR DECODE(T.ATTRIBUTE4, S.ATTRIBUTE4, 0, 1) = 1 OR DECODE(T.ATTRIBUTE5, S.ATTRIBUTE5, 0, 1) = 1 OR DECODE(T.ATTRIBUTE6, S.ATTRIBUTE6, 0, 1) = 1 OR DECODE(T.ATTRIBUTE7, S.ATTRIBUTE7, 0, 1) = 1 OR DECODE(T.ATTRIBUTE8, S.ATTRIBUTE8, 0, 1) = 1 OR DECODE(T.ATTRIBUTE9, S.ATTRIBUTE9, 0, 1) = 1 OR DECODE(T.ATTRIBUTE10, S.ATTRIBUTE10, 0, 1) = 1 OR DECODE(T.INPUT_TP_CD, S.INPUT_TP_CD, 0, 1) = 1
